[DataContractAttribute]
class HSMobileOpsSerialRequest
{
    DataAreaId     dataAreaId;
    ItemId         itemId;
    InventSerialId serialId;

}

Method.Source:
[DataMemberAttribute('DataAreaId')]
public DataAreaId parmDataAreaId(DataAreaId _value = dataAreaId)
{
    dataAreaId = _value;
    return dataAreaId;
}

[DataMemberAttribute('ItemId')]
public ItemId parmItemId(ItemId _value = itemId)
{
    itemId = _value;
    return itemId;
}

[DataMemberAttribute('SerialId')]
public InventSerialId parmSerialId(InventSerialId _value = serialId)
{
    serialId = _value;
    return serialId;
}
